 if(!skeleton)rim(c,[[-width+1,-32],[-width-6,-27],[-width-8+flutter,8],[-8+flutter,5],[1,10],[width+2,5],[width,-30]],dark);
 if(archer||kind==='ranger'){rim(c,[[-18,-27],[-12,-29],[-7,-6],[-13,-3]],'#624938');for(let i=0;i<4;i++){stroke(c,-17+i*2,-24,-21+i*2,-41,'#b9a06b');stroke(c,-22+i*2,-42,-19+i*2,-38,'#d8d9ae',2)}}
 // Eight distinct walk poses move knees, heels, and the opposite arm.
 for(const side of [-1,1]){const stride=Math.round(a.step*side*4),x=side*(tank?8:5),boot=x+stride;stroke(c,x,0,x+stride*.5,9,OUT,8);stroke(c,x+stride*.5,9,boot,16,OUT,7);stroke(c,x,0,x+stride*.5,8,armor?'#70818d':'#4c4d50',5);stroke(c,x+stride*.5,8,boot,16,armor?'#9cb1b9':'#59605b',4);box(c,boot-3,15,9,4,'#2c303a');box(c,boot-2,15,6,1,armor?'#d1d7c7':'#93775b');if(armor){box(c,x-3,3,6,6,'#adc0c4');stroke(c,x-2,4,x-2,8,'#e0e4ca')}}
 rim(c,[[-width,-27],[0,-31],[width,-27],[width,-4],[4,0],[-width,-2]],armor?'#7893a1':cloth);
 polygon(c,[[-width+1,-25],[-width+4,-26],[-width+3,-4],[-width+1,-3]],light);
 polygon(c,[[width-4,-25],[width-1,-24],[width-1,-4],[width-4,-2]],dark);
 if(skeleton){for(let i=0;i<4;i++){stroke(c,-6,-22+i*4,5,-21+i*4,skin,2);box(c,0,-23+i*4,2,3,'#eee2b6')}stroke(c,0,-25,0,-5,skin,2)}
 else if(armor){rim(c,[[-width+3,-25],[0,-28],[width-3,-25],[width-3,-9],[0,-5],[-width+3,-9]],'#afc0c7');stroke(c,-width+4,-23,width-4,-23,'#e2e6d0');stroke(c,0,-26,0,-8,'#eff2da');for(let y=-20;y<-8;y+=4){box(c,width-5,y,1,2,'#5b7486');box(c,-width+4,y,1,1,'#f1e5b6')}jewel(c,0,-17,tank?'#71bbd1':'#b86b56')}
 else{stroke(c,-7,-26,7,-6,'#5a3f36',3);stroke(c,-6,-26,7,-7,GOLD);for(let y=-22;y<-2;y+=4){box(c,-width+2,y,1,1,GOLD);if(robe)box(c,width-3,y,1,2,'#cbd0b0')}texture(c,-width+4,-24,width*2-8,18,light,kind.length,.1)}
 box(c,-width,-3,width*2+1,3,'#3b3030');rim(c,[[-3,-4],[3,-4],[3,1],[-3,1]],GOLD);box(c,-1,-2,2,2,'#72513c');box(c,-width,0,5,6,'#856444');box(c,-width+1,1,3,1,GOLD);
 // Sleeves and hands follow a wind-up, release, and recovery arc.
 const hx=16+Math.round(swing*8),hy=-14-Math.round(swing*6)-(a.cast?6:0),back=-14-Math.round(a.step*2);
 stroke(c,-width,-24,back,-8,OUT,7);stroke(c,-width,-24,back,-8,cloth,5);box(c,back-2,-9,4,4,skin);
 stroke(c,width,-24,hx,hy,OUT,7);stroke(c,width,-24,hx,hy,armor?'#a0b5bf':cloth,5);box(c,hx-2,hy-1,4,4,armor?'#c1d0cd':skin);box(c,hx-2,hy-2,4,1,GOLD);
 // Faces retain single-pixel eyes, brows, hair, and highlights.
 oval(c,0,-39,8,10,OUT);oval(c,0,-39,7,9,skin);polygon(c,[[-7,-42],[-5,-48],[4,-48],[8,-42],[5,-40],[1,-44],[-4,-43]],'#504139');box(c,-5,-40,2,1,'#956846');box(c,2,-40,3,1,'#5a4137');box(c,3,-38,2,2,'#182a32');box(c,4,-38,1,1,'#eef0ce');box(c,4,-33,2,1,'#a47658');box(c,-3,-44,3,1,'#f3d4a5');
 if(skeleton){box(c,-5,-41,3,4,OUT);box(c,2,-41,3,4,OUT);box(c,-1,-35,2,2,'#706952');for(let x=-4;x<5;x+=2)box(c,x,-31,1,2,'#6b624e')}
 if(armor){rim(c,[[-9,-44],[-6,-50],[5,-50],[10,-44],[9,-32],[-9,-32]],'#a9bec7');box(c,-7,-42,15,5,'#243544');box(c,-6,-40,12,1,'#719197');stroke(c,0,-49,0,-33,'#e3e4c6');stroke(c,-7,-46,-5,-48,'#d7e2d0');if(fighter){rim(c,[[-3,-50],[-4,-61],[0,-65],[5,-60],[4,-50]],'#aa4e49');stroke(c,0,-61,1,-52,'#ed9b6c')}else{box(c,-7,-31,14,3,'#809aa8');box(c,-5,-30,10,1,'#d2d9c5')}}
 else if(mage){rim(c,[[-12,-45],[-7,-51],[-3,-65],[3,-59],[9,-47],[14,-44],[5,-41],[-5,-41]],'#3b6c8d');stroke(c,-3,-61,1,-55,'#97bfcd');box(c,-9,-47,19,3,GOLD);jewel(c,2,-47,'#75d9e2')}
 else if(archer||assassin||cult){const hood=assassin?'#5d4a70':cult?dark:'#456c4c';rim(c,[[-9,-32],[-11,-44],[-5,-52],[4,-52],[11,-43],[8,-31],[5,-34],[5,-44],[-4,-45],[-6,-36]],hood);stroke(c,-7,-44,-4,-48,tint(hood,38));if(assassin){box(c,-5,-35,12,5,'#3f354f');box(c,2,-39,4,1,'#dccb9b')}}
 else if(healer){for(let i=0;i<25;i++){const t=i/25*TAU;box(c,Math.cos(t)*10,-56+Math.sin(t)*3,1,1,GOLD)}rim(c,[[-8,-46],[-3,-51],[5,-49],[9,-42],[6,-41],[0,-46]],'#c4d8ba')}
 else if(feral){for(const d of [-1,1]){stroke(c,d*5,-46,d*13,-57,'#aa9470',2);stroke(c,d*10,-53,d*9,-60,'#d5c6a0');stroke(c,d*12,-56,d*17,-57,'#d5c6a0')}rim(c,[[-9,-44],[-5,-49],[0,-45],[6,-49],[9,-43],[6,-39],[-6,-39]],'#72563f');box(c,2,-39,4,1,'#dcca86')}
 if(archer||kind==='ranger'){const bx=hx+5,draw=Math.round(swing*7);for(let i=-17;i<=17;i++){const bowX=bx+Math.round(Math.sqrt(Math.max(0,17*17-i*i))*.48);box(c,bowX,hy+i,2,1,'#b58e56');box(c,bowX,hy+i,1,1,'#e8c984')}stroke(c,bx,hy-17,bx-draw,hy,'#ded6af');stroke(c,bx-draw,hy,bx,hy+17,'#ded6af');if(a.attack){stroke(c,bx-draw-8,hy,bx+19,hy,'#c8af74');polygon(c,[[bx+22,hy],[bx+16,hy-3],[bx+17,hy+3]],'#e7e8c7')}}
 else if(mage||healer||cult){stroke(c,hx,hy+24,hx+4,hy-25,OUT,4);stroke(c,hx,hy+23,hx+4,hy-25,'#8b6a44',2);stroke(c,hx+1,hy+16,hx+4,hy-21,GOLD);jewel(c,hx+4,hy-29,healer?'#a6e9a5':cult?'#c290de':'#85d0e2');if(a.cast||a.attack){for(let i=0;i<4;i++){const t=a.clock+i*Math.PI/2;box(c,hx+4+Math.cos(t)*10,hy-29+Math.sin(t)*7,2,2,healer?'#d6ffc8':'#e6c6ff')}}}
 else if(feral){for(let i=0;i<3;i++)stroke(c,hx+i*3,hy+2+i,hx+12+i*3,hy-10-i,'#eee0bd',2)}
 else if(!skeleton){const angle=a.attack?-.9+a.attack*3.9:-1.15;blade(c,hx+2,hy+1,angle,fighter?35:assassin?21:25);if(assassin)blade(c,back,-5,-1.9-a.attack*1.7,17)}
